insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-barszcz', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-barszcz/efe9222b-f6b5-42df-a683-71394e5dbd21.webp', 25, 45, 4, null, null, '{}'::jsonb, '', array['post-barszcz-technik', 'post-polnische-suppen', 'post-smietana-schmand', 'post-wigilia', 'post-polenladen']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-barszcz', 'de', 'Barszcz czerwony', 'barszcz-czerwony', 'Klarer, rubinroter Rote-Bete-Sud zur Wigilia, streng vegetarisch und durchsichtig serviert, ganz anders als der dickere, fleischreiche Barszcz ukraiński und als die säuerliche Sauerteigsuppe Żurek.', '[{"text":"Schäle die Rote Bete, schneide sie in Würfel und koche sie zusammen mit Piment und Lorbeer in der Gemüsebrühe, bis sie weich ist.","tip":"Reibe dir die Hände vor dem Schälen mit etwas Öl ein, dann verfärben sich Finger und Schneidebrett weniger stark von der Rote Bete."},{"text":"Schmecke den Sud mit Knoblauch, Essig und einer Prise Zucker ab, bis er angenehm säuerlich-süß schmeckt und nicht fade wirkt.","tip":"Die Säure entscheidet über den ganzen Geschmack, probiere lieber zweimal ab, denn ein zu milder Barszcz wirkt schnell langweilig."},{"text":"Siebe den Sud für eine klare Festtagsbrühe ab oder lass ihn für den Alltag stückig, ganz nach Anlass.","tip":"Zur Wigilia gehört traditionell die klare Variante auf den Tisch, an gewöhnlichen Tagen darfst du die Rote-Bete-Stücke ruhig drinlassen."},{"text":"Serviere den Barszcz heiß, zur Wigilia klassisch mit Uszka in der Schale oder im Alltag mit gekochten Kartoffeln.","tip":"Koche die Uszka separat, Mengen und Falttechnik stehen im eigenen Rezept zu [Uszka](/de/rezepte/uszka), die Teigtaschen kommen erst am Tisch in die Suppe."}]'::jsonb, 'Barszcz czerwony, klar, säuerlich, festlich rot. Barszcz ist nach der Wildpflanze Barszcz benannt, dem Wiesenbärenklau, mit dem die Suppe ursprünglich sauer eingelegt und gekocht wurde, lange bevor die Rote Bete die Hauptzutat übernahm. Zur Wigilia, dem Heiligabend-Essen, gehört traditionell die klare, rubinrote Variante, denn die zwölf Gänge des Abends, benannt nach den zwölf Aposteln, müssen nach katholischer Fastenregel vollständig fleischlos bleiben. Weil kein Rinder- oder Hühnerfond zur Verfügung steht, holt sich der Wigilia-Barszcz seine Tiefe stattdessen aus getrockneten Steinpilzen, die stundenlang mitziehen und der Suppe trotz fehlendem Fleisch einen erdig-runden Geschmack geben. Die rote Farbe soll traditionell an das Blut Christi erinnern, und die kleinen, mit Pilzen gefüllten Teigtaschen Uszka verweisen auf die alte polnische Tradition des Pilzesammelns im Wald. Ganz anders ist der Barszcz ukraiński, der in Polen ebenfalls beliebt ist, ein dicker, fleischreicher Eintopf mit Kohl, Bohnen und Kartoffeln, der mit einem Klecks Sauerrahm serviert wird und mit der klaren Festtagsbrühe kaum mehr als die rote Farbe teilt. Verwechsle Barszcz außerdem nicht mit der sauren Sauerteigsuppe [Żurek](/de/rezepte/zurek), die ihre Säure aus fermentiertem Roggen statt aus Rote Bete zieht, oder mit der goldenen Hühnerbrühe [Rosół](/de/rezepte/rosol), die als klare Vorsuppe an gewöhnlichen Sonntagen serviert wird.

## Einkaufen und kochen

Frische Rote Bete, gute Gemüsebrühe, Piment im Ganzen sowie Essig oder etwas Zitronensäure zum Feinabschmecken reichen für den Ansatz. Uszka kochst du separat nach dem eigenen [Uszka](/de/rezepte/uszka)-Rezept, oder du holst fertige Teigtaschen im [Polenladen](/de/blog/polenladen-einkaufen), wenn vor der Wigilia die Zeit knapp wird. Getrocknete Steinpilze für den vollen, fleischlosen Geschmack findest du im selben Laden, meist deutlich günstiger als im deutschen Feinkostregal.

Für eine klare Festtagsbrühe siebst du den Sud ab, im Alltag darfst du ihn stückig lassen, das ist reine Geschmacksfrage. Justiere die Säure erst am Ende, denn zu langes Kochen macht den Geschmack flach und trübt die Farbe. Uszka kochst du nie in der Suppe selbst mit, sondern immer separat in Salzwasser, erst in der Schale kommen beide zusammen, sonst verlieren die Teigtaschen ihre Form und die Suppe wird stärkehaltig-trüb.

An Heiligabend in Deutschland trägt ein klarer Barszcz oft das ganze Menü, er verbindet Generationen am Tisch und lässt sich gut ein bis zwei Tage vorher vorbereiten, während die Uszka separat warten. Viele Familien nutzen genau diese Vorlaufzeit, um am 24. Dezember selbst mehr Ruhe zu haben, wenn ohnehin schon mehrere andere Wigilia-Gerichte gleichzeitig fertig werden müssen.

## Am Tisch

Serviere den Barszcz heiß, zur Wigilia mit Uszka aus dem eigenen Rezept in der Schale, im Alltag mit Kartoffeln oder Kartoffelklößen. Ein Schuss Sauerrahm bleibt an gewöhnlichen Tagen optional, gehört aber nicht in die klare Festtagsversion, denn genau die Klarheit macht diese Wigilia-Suppe aus.

Häufig wird Barszcz zu süß abgeschmeckt, durch zu starkes Kochen trüb, oder durch zu wenig Säure eher fade als lebendig. Er soll wach und klar schmecken, nicht wie ein süßer Saft. Uszka gehören außerdem nicht stundenlang in die heiße Suppe, sie werden erst kurz vor dem Servieren in der Schale zusammengeführt, sonst verlieren sie ihre Form und die Brühe wird stärkehaltig.

Du kannst getrocknete Pilze großzügiger in den Ansatz geben, mehr Knoblauch betonen oder für den Alltag eine schärfere, stückige Variante kochen. Kiszone Suppen ganz ohne Rote Bete sind ein eigenes Kapitel, etwa die saure [Ogórkowa](/de/rezepte/ogorkowa) oder der Kraut-Eintopf [Kapuśniak](/de/rezepte/kapusniak), und eine warme Frühlingsversion mit jungen Blättern findest du bei [Botwinka](/de/rezepte/botwinka). Verwechsle den klaren Wigilia-Barszcz nie mit dem dicken, fleischreichen Barszcz ukraiński, das sind zwei ganz verschiedene Traditionen unter demselben Namen.', 'Barszcz czerwony Rezept | Alemniam', 'Polnischer Barszcz czerwony: klarer Rote-Bete-Eintopf zur Wigilia, bilingual mit DE-Einkaufstipps.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-barszcz', 'pl', 'Barszcz czerwony', 'barszcz-czerwony', 'Klarowny, rubinowoczerwony wywar z buraków na Wigilię, ściśle wegetariański i przejrzysty, zupełnie inny niż gęsty, mięsny barszcz ukraiński i inny niż kwaśny żurek na zakwasie.', '[{"text":"Obierz buraki, pokrój je w kostkę i gotuj razem z zielem angielskim i liściem laurowym w bulionie warzywnym, aż będą miękkie.","tip":"Przed obieraniem natrzyj ręce odrobiną oleju, wtedy palce i deska mniej się barwią od buraka."},{"text":"Dopraw wywar czosnkiem, octem i szczyptą cukru, aż będzie przyjemnie kwaśno-słodki, a nie mdły.","tip":"Kwasowość decyduje o całym smaku, spróbuj dwa razy, bo zbyt łagodny barszcz szybko robi się nudny."},{"text":"Przecedź wywar dla klarownego barszczu świątecznego albo zostaw go z warzywami na co dzień, zależnie od okazji.","tip":"Na Wigilię tradycyjnie podaje się wersję klarowną, w zwykłe dni możesz spokojnie zostawić kawałki buraka."},{"text":"Podawaj barszcz gorący, na Wigilię klasycznie z uszkami w misce albo na co dzień z ugotowanymi ziemniakami.","tip":"Uszka gotuj osobno, ilości i sposób lepienia znajdziesz w osobnym przepisie na [uszka](/pl/rezepte/uszka), pierożki trafiają do zupy dopiero przy stole."}]'::jsonb, 'Barszcz czerwony, klarowny, kwaśny, odświętnie czerwony. Barszcz zawdzięcza nazwę dzikiej roślinie zwanej barszczem zwyczajnym, którą dawniej kiszono i gotowano na kwaśno, długo przed tym, jak główną rolę przejął burak. Na Wigilię tradycyjnie podaje się klarowną, rubinowoczerwoną wersję, bo dwanaście dań tego wieczoru, nazwanych na cześć dwunastu apostołów, musi według katolickiej reguły postu być całkowicie bezmięsnych. Skoro nie ma wywaru z wołowiny czy kurczaka, wigilijny barszcz czerpie głębię smaku z suszonych borowików, które gotują się godzinami i dają zupie ziemisty, pełny smak mimo braku mięsa. Czerwony kolor ma tradycyjnie przypominać krew Chrystusa, a małe pierożki z grzybami, uszka, odwołują się do dawnej polskiej tradycji grzybobrania. Zupełnie inny jest popularny w Polsce barszcz ukraiński, gęsty, mięsny gulasz z kapustą, fasolą i ziemniakami, podawany z łyżką śmietany, który z klarowną wersją świąteczną łączy właściwie tylko czerwony kolor. Nie myl barszczu też z kwaśnym [żurkiem](/pl/rezepte/zurek) na zakwasie żytnim, którego kwasowość pochodzi z fermentacji, a nie z buraka, ani ze złotym [rosołem](/pl/rezepte/rosol), klarowną zupą z kurczaka podawaną na zwykłe niedzielne obiady.

## Zakupy i gotowanie

Świeże buraki, dobry bulion warzywny, całe ziele angielskie oraz ocet lub odrobina kwasku cytrynowego do doprawienia wystarczą na bazę. Uszka gotujesz osobno według własnego przepisu na [uszka](/pl/rezepte/uszka), a gotowe pierożki na wypadek braku czasu przed Wigilią kupisz w [sklepie polskim](/pl/blog/sklep-polski-zakupy). Suszone borowiki na pełny, bezmięsny smak znajdziesz w tym samym sklepie, zwykle znacznie taniej niż w niemieckim delikatesowym regale.

Dla klarownego barszczu świątecznego przecedź wywar, na co dzień możesz zostawić go z warzywami, to czysta kwestia smaku. Kwasowość ustawiaj na końcu, bo zbyt długie gotowanie spłaszcza smak i mętni kolor. Uszek nigdy nie gotuj w samej zupie, tylko zawsze osobno w osolonej wodzie, łącz je z barszczem dopiero w misce, inaczej pierożki się rozpadają, a zupa robi się mętna od skrobi.

W Wigilię w Niemczech klarowny barszcz często niesie całe menu, łączy pokolenia przy stole i da się przygotować dzień lub dwa wcześniej, podczas gdy uszka czekają osobno. Wiele rodzin wykorzystuje właśnie ten czas, żeby 24 grudnia mieć więcej spokoju, gdy i tak trzeba na czas skończyć kilka innych wigilijnych dań.

## Przy stole

Podawaj barszcz gorący, na Wigilię z uszkami z osobnego przepisu w misce, na co dzień z ziemniakami albo z kluskami. Łyżka śmietany zostaje opcjonalna na zwykłe dni, ale nie pasuje do klarownej wersji świątecznej, bo właśnie przejrzystość definiuje tę wigilijną zupę.

Barszcz często wychodzi zbyt słodki, mętny przez zbyt gwałtowne gotowanie albo płaski przez za mało kwasu. Ma smakować świeżo i klarownie, a nie jak słodki sok. Uszek też nie wolno godzinami trzymać w gorącej zupie, łączy się je w misce dopiero na chwilę przed podaniem, inaczej tracą formę, a bulion robi się skrobiowo mętny.

Możesz dodać więcej suszonych grzybów do bazy, mocniej podkreślić czosnek albo na co dzień ugotować ostrzejszą wersję z warzywami w kawałkach. Zupy kiszone bez buraków to zupełnie inny rozdział, na przykład kwaśna [ogórkowa](/pl/rezepte/ogorkowa) czy kapuściany [kapuśniak](/pl/rezepte/kapusniak), a ciepłą wiosenną wersję z młodymi listkami znajdziesz przy [botwince](/pl/rezepte/botwinka). Nie myl klarownego barszczu wigilijnego z gęstym, mięsnym barszczem ukraińskim, to dwie zupełnie różne tradycje pod tą samą nazwą.', 'Barszcz czerwony przepis | Alemniam', 'Barszcz czerwony: klarowny wywar z buraków na Wigilię, przepis dwujęzyczny z listą zakupów.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
